import{_ as a,c as o,o as n,ai as r}from"./chunks/framework.CcmNAoqQ.js";const c=JSON.parse('{"title":"NeoNephos Webinar","description":"","frontmatter":{"title":"NeoNephos Webinar","date":"2026-07-06","banner":"assets/blog/20260706_neonephos_webinar_banner.svg","authors":["neonephos-team"],"tags":["2026","news"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"BlogEntryThemeComponent"},"headers":[],"relativePath":"blog/20260706_webinar.md","filePath":"blog/20260706_webinar.md"}'),t={name:"blog/20260706_webinar.md"};function s(i,e,u,l,p,h){return n(),o("div",null,e[0]||(e[0]=[r('<h1 id="neonephos-webinar" tabindex="-1">NeoNephos Webinar <a class="header-anchor" href="#neonephos-webinar" aria-label="Permalink to &quot;NeoNephos Webinar&quot;">​</a></h1><h2 id="neonephos-and-europe" tabindex="-1">NeoNephos and Europe <a class="header-anchor" href="#neonephos-and-europe" aria-label="Permalink to &quot;NeoNephos and Europe&quot;">​</a></h2><p>As alluded to in <a href="https://www.techzine.eu/experts/devops/139288/advancing-europes-public-agenda-through-open-source-software-foundations/" target="_blank" rel="noreferrer">Advancing Europe&#39;s Open Source Agenda through Open Source Software Foundations</a>, supranational sovereignty cannot be forced upon but must be built through community acceptance. Such community acceptance requires trust, which is earned in spades but can easily be lost in buckets. <a href="https://www.linuxfoundation.org/press/linux-foundation-and-industry-leaders-launch-akrites-to-defend-critical-open-source-software-against-ai-enabled-cyber-threats" target="_blank" rel="noreferrer">Especially in the age of AI</a>, enterprise hardened open source software <a href="https://www.linuxfoundation.org/resources/publications/linux-foundation-annual-report-2025" target="_blank" rel="noreferrer">demonstrably benefits</a> from a structured development umbrella: Even &quot;simple&quot; projects nowadays often require infrastructure, token credits, a formalized vulnerability management process etc. to gain any meaningful traction in the community. These are all things which may be prohibitive for a small group of hobbyist maintainers. Therefore, to attract contributors in order to advance supranational sovereignty, a shared development vehicle must offer all these facilities and beyond.</p><p>Learn on July 10 at 11:00 AM CEST about how the NeoNephos Foundation addresses these issues and more. We invited a cross-company panel to discuss and share how we can shape Europe&#39;s next generation of open cloud infrastructure.</p><ul><li>Christian Hüning – Product Manager at BWI GmbH &amp; Governing Board Member, NeoNephos Foundation</li><li>Orlin Vasilev – Open Source Advocate at SAP &amp; Governing Board Chair, NeoNephos Foundation</li><li>Vasu Chandrasekhara – Advisor to the NeoNephos Foundation</li></ul><p><a href="https://events.sap.com/ospo-webinar-series/en_us/home.html" target="_blank" rel="noreferrer">Register for the NeoNephos webinar</a>!</p>',6)]))}const b=a(t,[["render",s]]);export{c as __pageData,b as default};
